@page "/chat"
@using sv_80cd7ff383d5457d9f780def340d6804.Services
@inject IChatService ChatService
@rendermode InteractiveServer

<PageTitle>Chat</PageTitle>

<div class="chat-layout @(_threadOpen ? "thread-open" : "")">
    <ChannelSidebar Channels="_channels"
                    ActiveChannelId="_activeChannel?.Id"
                    OnChannelSelected="SelectChannel" />

    <MessagePanel Channel="_activeChannel"
                  Messages="_messages"
                  ThreadReplyCounts="_threadReplyCounts"
                  IsLoadingMore="_loadingMore"
                  OnLoadMore="LoadOlderMessages"
                  OnOpenThread="OpenThread"
                  OnReact="HandleReaction"
                  OnSendMessage="SendMessage" />

    @if (_threadOpen)
    {
        <ThreadPanel RootMessage="_threadRootMessage"
                     Replies="_threadReplies"
                     OnClose="CloseThread"
                     OnSendReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> _channels = new();
    private Channel? _activeChannel;
    private List<Message> _messages = new();
    private Dictionary<int, int> _threadReplyCounts = new();
    private bool _loadingMore;
    private const int PageSize = 30;

    // Thread state
    private bool _threadOpen;
    private Message? _threadRootMessage;
    private List<Message> _threadReplies = new();

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
    }

    private async Task SelectChannel(Channel channel)
    {
        _activeChannel = channel;
        _messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        await ChatService.MarkChannelReadAsync(channel.Id);
        await LoadThreadCounts();
        CloseThreadSync();
        StateHasChanged();
    }

    private async Task LoadOlderMessages()
    {
        if (_activeChannel is null || _loadingMore) return;
        _loadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_activeChannel.Id, _messages.Count, PageSize);
        if (older.Count > 0)
        {
            _messages.InsertRange(0, older);
            await LoadThreadCounts();
        }
        _loadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (_activeChannel is null) return;
        var msg = await ChatService.SendMessageAsync(_activeChannel.Id, content, null);
        _messages.Add(msg);
    }

    private async Task OpenThread(Message message)
    {
        _threadRootMessage = message;
        _threadReplies = await ChatService.GetThreadAsync(message.Id);
        _threadOpen = true;
    }

    private void CloseThreadSync()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = new();
    }

    private Task CloseThread()
    {
        CloseThreadSync();
        return Task.CompletedTask;
    }

    private async Task SendThreadReply(string content)
    {
        if (_activeChannel is null || _threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(_activeChannel.Id, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);

        // Update reply count
        _threadReplyCounts[_threadRootMessage.Id] = _threadReplies.Count;
    }

    private async Task HandleReaction(MessageItem.ReactionRequest request)
    {
        await ChatService.AddReactionAsync(request.MessageId, request.Emoji);
        // Refresh messages to show updated reactions
        if (_activeChannel is not null)
        {
            _messages = await ChatService.GetMessagesAsync(_activeChannel.Id, 0, _messages.Count);
        }
    }

    private async Task LoadThreadCounts()
    {
        _threadReplyCounts.Clear();
        // Identify thread starters (messages that have no ReplyToId and could have replies)
        foreach (var msg in _messages.Where(m => m.ReplyToId is null))
        {
            var thread = await ChatService.GetThreadAsync(msg.Id);
            if (thread.Count > 0)
            {
                _threadReplyCounts[msg.Id] = thread.Count;
            }
        }
    }
}

