    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.25rem;
    transition: background 0.15s;
}

::deep .channel-item:hover {
    background: #3a3d5c;
}

::deep .channel-item.active {
    background: #4a4e8a;
