::deep .channel-name {
    font-weight: 600;
    font-size: 0.95rem;
    flex: 1;
}

::deep .channel-description {
    font-size: 0.75rem;
    color: #8d99ae;
    width: 100%;
}

::deep .unread-badge {
    background: #ef233c;
    color: white;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 0.15rem 0.5rem;
    border-radius: 10px;
    min-width: 1.2rem;
    text-align: center;
}

/* Message Panel */
::deep .message-panel {
    display: flex;
    flex-direction: column;
    height: 100vh;
    overflow: hidden;
    background: #f8f9fa;
}

::deep .panel-header {
    padding: 1rem 1.5rem;
    border-bottom: 1px solid #dee2e6;
    background: white;
}

::deep .channel-title {
    margin: 0;
    font-size: 1.2rem;
}

::deep .channel-desc {
    margin: 0.25rem 0 0;
    font-size: 0.85rem;
    color: #6c757d;
}

::deep .no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: #6c757d;
}

/* Message List */
::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 1rem 1.5rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

::deep .loading-indicator {
    text-align: center;
    padding: 0.5rem;
    color: #6c757d;
    font-size: 0.85rem;
}

::deep .message-item {
    padding: 0.6rem 0.8rem;
    border-radius: 6px;
    position: relative;
    transition: background 0.15s;
}

::deep .message-item:hover {
    background: #e9ecef;
}

::deep .message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
    margin-bottom: 0.2rem;
}

::deep .message-author {
    font-weight: 700;
    font-size: 0.9rem;
}

::deep .message-time {
    font-size: 0.75rem;
    color: #6c757d;
}

::deep .message-content {
    font-size: 0.9rem;
    line-height: 1.4;
    margin: 0;
}

::deep .message-reactions {
    display: flex;
    gap: 0.3rem;
    margin-top: 0.4rem;
    flex-wrap: wrap;
}

