    background: white;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 0.3rem;
    display: flex;
    gap: 0.2rem;
    box-shadow: 0 4px 8px rgba(0,0,0,0.15);
    z-index: 10;
}

::deep .emoji-option {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 0.2rem 0.4rem;
    border-radius: 3px;
}

::deep .emoji-option:hover {
    background: #e9ecef;
}

/* Message Input */
::deep .message-input-area {
    display: flex;
    gap: 0.5rem;
    padding: 0.8rem 1.5rem;
    background: white;
    border-top: 1px solid #dee2e6;
    align-items: flex-end;
}

::deep .message-textarea {
    flex: 1;
    resize: none;
    border: 1px solid #dee2e6;
    border-radius: 6px;
