    font-family: inherit;
}

::deep .message-textarea:focus {
    outline: none;
    border-color: #6ea8fe;
    box-shadow: 0 0 0 2px rgba(13,110,253,0.15);
}

::deep .send-btn {
    background: #0d6efd;
    color: white;
    border: none;
    border-radius: 6px;
    padding: 0.6rem 1.2rem;
    font-weight: 600;
    cursor: pointer;
    white-space: nowrap;
}

::deep .send-btn:hover:not(:disabled) {
    background: #0b5ed7;
}

::deep .send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Thread Panel */
::deep .thread-panel {
    display: flex;
    flex-direction: column;
    height: 100vh;
    background: white;
    border-left: 1px solid #dee2e6;
    overflow: hidden;
}

::deep .thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 1rem 1.2rem;
    border-bottom: 1px solid #dee2e6;
}

::deep .thread-header h3 {
    margin: 0;
    font-size: 1.1rem;
}

::deep .close-btn {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 0.2rem 0.5rem;
    border-radius: 4px;
    color: #6c757d;
}

::deep .close-btn:hover {
    background: #e9ecef;
    color: #212529;
}

::deep .thread-root-message {
    padding: 0.8rem 1.2rem;
    background: #f8f9fa;
    border-bottom: 1px solid #dee2e6;
}

::deep .thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 0.8rem 1.2rem;
    display: flex;
    flex-direction: column;
    gap: 0.6rem;
}

::deep .thread-reply {
    padding: 0.4rem 0;
}

